import{z as d,x as B,o as n,c as p,q as l,j as i,D as t,d as r,s,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"快排与期望","description":"","frontmatter":{"title":"快排与期望","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/quicksort-expected.md","filePath":"cs/quicksort-expected.md","lastUpdated":1791063341000}'),A={name:"cs/quicksort-expected.md"};function c(h,a,u,m,D,T){const o=B("Mermaid");return n(),p("div",null,[a[2]||(a[2]=l('<h1 id="快排与期望" tabindex="-1">快排与期望 <a class="header-anchor" href="#快排与期望" aria-label="Permalink to &quot;快排与期望&quot;">​</a></h1><div class="epigraph"><p>随机轴元把输入的次序洗进期望；最坏平方仍可能，期望比较次数却是 $O(n\\log n)$。</p><footer>—— 据 Hoare, Quicksort, 1962；CLRS 第 7 章整理</footer></div><p>上一课<a href="/cs/heapsort">堆排序</a>给出最坏 \\(\\Theta(n\\log n)\\) 的就地比较排序。本课不重写下滤。缺口是：实践里更常见的是<strong>分区</strong>：选一个轴，小于的在左、大于的在右，再递归。最坏仍平方；要用<a href="/cs/discrete-probability">离散概率</a>把代价写成期望，而不是再发明一种堆。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Hoare 的分区把规模切成 \\(q\\) 与 \\(n-q-1\\)。切法不保证对半：已排序数组上固定取末元，递归退化成 \\(T(n)=T(n-1)+\\Theta(n)\\)，平方。堆排序没有这个问题，但它不分区、也不把相等键聚在轴两侧。缺口不是再证主定理，而是：<strong>随机选轴（或先随机打乱）之后，期望比较次数是 \\(O(n\\log n)\\)</strong>。</p><p>本课仍在比较模型、仍在 P。指示器分析不需要图灵机。确定性最坏线性选择轴是<a href="/cs/select-kth">选择第 k 小</a>才启用的；快排主干用随机就够。</p><h3 id="期望不是平均输入" tabindex="-1">期望不是平均输入 <a class="header-anchor" href="#期望不是平均输入" aria-label="Permalink to &quot;期望不是平均输入&quot;">​</a></h3><p>「对所有排列等概率」与「算法自己抛硬币」不是同一句话。本课采用后者：轴均匀随机，对任意固定输入谈期望。这样最坏输入不再特殊，期望由对称性给出。</p><p><span class="marginnote">指示器 \\(X_{ij}\\)：算法是否比较过秩为 \\(i\\) 与 \\(j\\) 的两个键。它们被比较当且仅当二者之一先当轴、且中间没有更早的轴。\\(\\Pr=\\frac{2}{j-i+1}\\)，求和即 \\(O(n\\log n)\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>partition</code> 的不变式：扫描指针左侧小于轴、右侧未处理。递归对两段调用。期望：\\(T(n)\\) 对切点均匀平均，主定理不能直接套（\\(b\\) 随机）。改用指示器，或写出 \\(T(n)=\\frac{1}{n}\\sum_q\\bigl(T(q)+T(n-q-1)\\bigr)+\\Theta(n)\\) 再解。</p>',11)),(n(),i(E,null,{default:t(()=>[s(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%95%B0%E7%BB%84%22%5D%20--%3E%20PIV%5B%22%E9%9A%8F%E6%9C%BA%E8%BD%B4%22%5D%0A%20%20PIV%20--%3E%20PART%5B%22%E5%88%86%E5%8C%BA%22%5D%0A%20%20PART%20--%3E%20L%5B%22%E9%80%92%E5%BD%92%E5%B7%A6%22%5D%0A%20%20PART%20--%3E%20R%5B%22%E9%80%92%E5%BD%92%E5%8F%B3%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"空间：就地分区，额外主要是递归栈；期望深度 \\(O(\\log n)\\)，最坏 \\(n\\)。尾递归消一侧可压栈，本课点名不实现。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"工程上常三数取中或随机打乱一次再固定取末元，期望同类。相等键要用三路分区，否则大量重复会退化；本课承认这件事，不把 Bentley–McIlroy 写完。稳定性默认没有：分区交换打乱相等键。",-1)),a[6]||(a[6]=e("p",null,"与堆排对照：期望更快、缓存更友好（顺序扫），最坏要靠随机或回退。本课不把「实际最快」当成定理。",-1)),(n(),i(E,null,{default:t(()=>[s(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%224%20%E4%B8%AA%E9%94%AE%3A%20%E7%A7%A9%20i%20%E4%B8%8E%20j%20%E8%B0%81%E5%85%88%E5%BD%93%E8%BD%B4%3F%22%5D%20--%3E%20A%7B%22i..j%20%E5%8C%BA%E9%97%B4%E5%86%85%22%7D%0A%20%20A%20--%3E%7C%22%E8%BD%B4%E6%98%AF%20i%20%E6%88%96%20j%22%7C%20B%5B%22%E4%BA%8C%E8%80%85%E8%A2%AB%E6%AF%94%E8%BE%83%22%5D%0A%20%20A%20--%3E%7C%22%E8%BD%B4%E5%9C%A8%20i%20%E4%B8%8E%20j%20%E4%B9%8B%E9%97%B4%22%7C%20C%5B%22%E4%BA%8C%E8%80%85%E6%B0%B8%E4%B8%8D%E6%AF%94%E8%BE%83%22%5D%0A%20%20B%20--%3E%20D%5B%22%E6%AF%8F%E4%B8%AA%E5%80%99%E9%80%89%E8%BD%B4%E7%AD%89%E6%A6%82%E7%8E%87%22%5D%0A%20%20D%20--%3E%20E%5B%22%E6%AF%94%E8%BE%83%E6%A6%82%E7%8E%87%20%3D%202%2F%E5%8C%BA%E9%97%B4%E9%95%BF%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p><span class="marginnote">数字实例：秩 2 与秩 6 的两个键，它们之间夹着 \\(6-2+1=5\\) 个候选轴。轴恰是这两个键之一（概率 \\(2/5\\)）时二者才被比较。把这 \\(2/(j-i+1)\\) 对所有 \\(\\binom{n}{2}\\) 对求和，得期望约 \\(2n\\ln n\\) 次比较——\\(n=10^5\\) 时约 230 万次，远低于平方的 100 亿次。</span></p><p><span class="marginnote">常见误区：初学者容易以为「期望 \\(O(n\\log n)\\)」是在说输入都差不多。实际上随机快排对<strong>每一个</strong>固定输入（哪怕敌方精心构造的已排序数组）谈期望，因为硬币是算法自己抛的——这正是「随机轴」比「平均输入假设」更强的地方。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证比较排序下界，不引入计数排序。最坏 \\(\\Theta(n^2)\\) 仍在；若必须最坏 \\(n\\log n\\)，用堆或后面的最坏线性选择做轴。也不处理并行快排与外部排序。</p><p>后课默认：快排期望 \\(O(n\\log n)\\)，最坏平方；分析工具是指示器。下界课问：比较模型里能否整体再快。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>随机快排期望 \\(O(n\\log n)\\)，最坏仍平方。</li><li>期望对算法的硬币，不是假定输入均匀。</li><li>就地、默认不稳；栈深期望对数。</li><li>出处：Hoare, 1962；CLRS 第 7 章；Knuth, TAOCP vol. 3。</li></ul>',7))])}const _=d(A,[["render",c]]);export{g as __pageData,_ as default};
